gn;d="${now}salarioimpuestos.txt";LC_NUMERIC=es_ES.UTF-8;echo $d;i=1;j=35;while (( i <= j ));do impuesto=0;k=$((i*1000));if (( k < 12450 ));then impuesto=0;elif (( k < 20200 ));then impuesto=$(echo "scale=2;(( $k - 12450 ) * 0.24 )" | bc);elif (( k < 35200 ));then impuesto=$(echo "scale=2;(( 20200 * 0.24 ) + (( $k - 20200 ) * 0.30 ))" | bc) ;fi;printf "%d\t%s\n" $k ${impuesto};i=$((i+1));done
